/* Global editor bridge — any view component that has an InlineDocEditorModal

   registers its setEditingDoc here so that openDocInNewTab (called from row

   clicks, card clicks, etc.) can open the editor directly without needing

   access to the component's closure. */

window._openDocEditor = window._openDocEditor || null;

window._registerDocEditor = function(setter) { window._openDocEditor = setter; };

window._unregisterDocEditor = function() { window._openDocEditor = null; };



/* Global preview bridge — the active document view registers its preview

   state setter here so openDocInNewTab opens the INLINE document viewer modal

   (DocumentPreviewModal) for EVERY document, regardless of type. */

window._openDocPreview = window._openDocPreview || null;

window._registerDocPreview = function(setter) { window._openDocPreview = setter; };

window._unregisterDocPreview = function() { window._openDocPreview = null; };



/* Open a document — v12.32.50-inline: EVERY document opens in the inline

   document viewer modal (DocumentPreviewModal via the global preview bridge).

   No new-tab or auto-download fallbacks — the viewer renders Drive docs, ERP

   content docs, text/HTML and DB-served PDFs/images with full visual elements.

   Falls back to the inline editor bridge, then legacy new-tab/download, only

   when no preview bridge is registered. */

var openDocInNewTab=doc=>{

    if(!doc)return;

    // ── Task 20: count every document preview load (best-effort beacon) ──
    try{
      var _mb=(window.__ERP_SITE_URL||'https://sr-ue-varna.com').replace(/\/$/,'')+'/database/metrics.php?record=erp_doc_preview_loads_total&delta=1&_='+Date.now();
      var _img=new Image();_img.src=_mb;
    }catch(_){}

    // ── Primary: inline viewer modal for ALL documents ──

    if(typeof window._openDocPreview==='function'){window._openDocPreview(doc);return}

    // For ANY document with a usable Drive ID, try the inline editor first

    // v12.27.1-404fix: Also reject short IDs (< 25 chars) — real Drive file IDs are 28+

    var _fid=doc.driveId||doc.id||doc.fileId||'';

    var _hasDriveId=_fid&&_fid.length>=25&&!/^(s_|doc_|up_|f_|copied_)/.test(_fid);

    if(_hasDriveId&&typeof window._openDocEditor==='function'){window._openDocEditor(doc);return}

    // Fallback: Google Docs with edit link

    var _isGD=doc.isGoogleDoc||!!(doc.mimeType||'').match(/google\.(document|spreadsheet|presentation|drawing|form)/i);

    var _editUrl=doc.googleDocEditLink||doc.editLink||doc.webViewLink||'';

    if(_isGD&&_editUrl&&typeof window._openDocEditor==='function'){window._openDocEditor(doc);return}

    if(doc.webViewLink){window.open(doc.webViewLink,'_blank','noopener,noreferrer');return}

    // v12.32.52-nodownload: opening a document to VIEW must never auto-download.

    // If we only have a raw downloadUrl (no inline preview editor registered),

    // open it in a new tab for viewing instead of triggering a file download.

    if(doc.downloadUrl){

        const _view=doc.webViewLink||doc.previewLink||doc.downloadUrl;

        window.open(_view,'_blank','noopener,noreferrer');return

    }

    if(doc.content){

    const safeName=String(doc.name||'Документ').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','\"':'&quot;','\'':'&#39;'}[c]));

    const safeBody=String(doc.content).replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]));

    const html='<!doctype html><html lang="bg"><head><meta charset="utf-8"><title>'+safeName+'</title>'

        +'<meta name="viewport" content="width=device-width,initial-scale=1">'

        +'<style>'

        +'body{margin:0;background:#f2f2f2;font-family:"Open Sans",system-ui,sans-serif;color:#1a1a1a;line-height:1.7}'

        +'header{background:#233874;color:#fff;padding:1rem 1.5rem;font-family:Merriweather,Georgia,serif;box-shadow:0 2px 8px rgba(0,0,0,.15);position:sticky;top:0;z-index:10}'

        +'header h1{margin:0;font-size:1.05rem;font-weight:700}'

        +'main{max-width:880px;margin:1.5rem auto;background:#fff;padding:2rem 2.4rem;border-radius:10px;box-shadow:0 2px 12px rgba(0,0,0,.06);border-top:3px solid #233874}'

        +'pre{white-space:pre-wrap;word-wrap:break-word;font-family:inherit;font-size:.92rem;margin:0}'

        +'@media(max-width:640px){main{margin:.5rem;padding:1.2rem}}'

        +'</style></head><body><header><h1>'+safeName+'</h1></header><main><pre>'+safeBody+'</pre></main></body></html>';

    const blob=new Blob([html],{type:'text/html;charset=utf-8'});

    const url=URL.createObjectURL(blob);

    const win=window.open(url,'_blank','noopener,noreferrer');

    setTimeout(()=>URL.revokeObjectURL(url),60000);

    if(!win)toast('Отварянето е блокирано от браузъра. Разрешете изскачащи прозорци.','error');

    return;

    }

    toast('Документът няма съдържание за визуализация','warn');

};



