const[docMode,setDocMode]=useState('browse'); // 'browse' | 'manage'



// ── Non-admin users see only project-type document categories ──

// Per requirement v4.4.0: fixed tab order — project-type forms first, then normative docs.

// Other auto-discovered categories are hidden from the tab bar.

const BASE_CATS=isAdmin

  ?['ФНИ','ПНИ','ДНП','НПФ','Нормативни','Критерии','Насоки','Шаблони']

  :['ФНИ','ПНИ','ДНП','НПФ'];



const categoryCounts=useMemo(()=>{
    // v12.49.45-docbuckets: count EVERY category getDocCategory() returns —
    // not just a hardcoded BASE_CATS list. Previously docs classified as
    // 'ПСП', 'Нормативни', 'Критерии', 'Шаблони', 'Насоки' or a raw folder
    // name were silently dropped (hasOwnProperty guard), so they vanished
    // from the library and looked "missing". Now they get their own count
    // and their own tab (see `categories` below).
    const counts={};
    documents.forEach(doc=>{
        const cat=getDocCategory(doc);
        const key=cat||'Общи';
        counts[key]=(counts[key]||0)+1;
    });
    return counts;
},[documents]);



const categories=useMemo(()=>{
    // Always show the canonical project-type tabs so users can see every
    // section, even when a type currently has 0 documents in the library.
    const CANON=['ФНИ','ПНИ','ДНП','НПФ','ПСП','Нормативни','Критерии','Шаблони','Насоки','Библиотека','Общи документи','Мои документи'];
    const present=Object.keys(categoryCounts).filter(c=>c!=='Общи');
    const all=CANON.slice();
    // Append any additional categories found in the data (raw folder names, etc.)
    present.forEach(c=>{ if(!all.includes(c)) all.push(c); });
    return isAdmin ? ['all'].concat(all) : all;
},[categoryCounts,isAdmin]);



const _DOC_CACHE_KEY='erp:docs:cache';

const _docCacheGet=()=>{try{const r=localStorage.getItem(_DOC_CACHE_KEY);if(!r)return null;const p=JSON.parse(r);if(Date.now()-p.ts>1800000)return null;return p.data||[];}catch(_){return null}};

const _docCacheSet=data=>{try{localStorage.setItem(_DOC_CACHE_KEY,JSON.stringify({ts:Date.now(),data}));}catch(_){}};



const loadDriveDocs=useCallback(async(forceRefresh=false)=>{

    if(!forceRefresh&&fetchDoneRef.current)return;

    fetchDoneRef.current=true;

    setDriveLoading(true);

    setDriveError(null);

    try{

    // 1. Hydrate from localStorage for instant paint on tab switch

    const cached=_docCacheGet();

    if(cached&&cached.length){setDocuments(mergeDocuments(cached))}

    // 2. Fetch fresh

    const baseUserId=(typeof _currentUserEmail!=='undefined'&&_currentUserEmail)||'';

    const payload=isAdmin

        ?_withAdmin({isAdmin:true,forceRefresh:!!forceRefresh})

        :{isAdmin:false,forceRefresh:!!forceRefresh,userId:baseUserId};

    const res=await api('listDocuments',payload);

    const driveDocs=Array.isArray(res.documents||(res.data&&res.data.documents))?(res.documents||res.data.documents):[];

    setDocuments(mergeDocuments(driveDocs));

    _docCacheSet(driveDocs); // persist for instant tab-switch reload

    }catch(err){

    if(!err.message||!err.message.includes('Unknown action')){

        setDriveError('Drive файловете не могат да бъдат заредени: '+err.message);

    }

    }finally{

    setDriveLoading(false);

    }

},[isAdmin]);



useEffect(()=>{loadDriveDocs()},[loadDriveDocs]);

// E3 breadcrumb: open document name as sub-path (tab label is rendered by the shell)
useEffect(()=>{try{if(window.App&&typeof window.App.setBreadcrumb==='function')window.App.setBreadcrumb(previewDoc&&previewDoc.name?[{label:previewDoc.name}]:[]);}catch(_){}},[loadDriveDocs,previewDoc]);

// E3 breadcrumb: clear the trail when DocumentsView unmounts
useEffect(()=>{return()=>{try{if(window.App&&typeof window.App.setBreadcrumb==='function')window.App.setBreadcrumb([]);}catch(_){}};},[]);

// v12.17.3: refresh when DB data changes (version poller detected change)

useEffect(()=>{

    var h=function(){loadDriveDocs(true)};

    window.addEventListener('erp:data-changed',h);

    return()=>window.removeEventListener('erp:data-changed',h);

},[loadDriveDocs]);



const handleRefresh=useCallback(()=>{

    fetchDoneRef.current=false;

    setDocuments(STATIC_DOCUMENTS);

    setDriveError(null);

    loadDriveDocs(true);

},[loadDriveDocs]);



const filtered=useMemo(()=>{

    let items=documents;

    if(activeCategory!=='all'){items=items.filter(doc=>getDocCategory(doc)===activeCategory)}

    if(searchDeferred.trim()){

    const q=searchDeferred.toLowerCase();

    items=items.filter(d=>(d.name||'').toLowerCase().includes(q)||(d.folderName||'').toLowerCase().includes(q));

    }

    // Natural sort so "Документ 2" precedes "Документ 10"

    try{items=items.slice().sort((a,b)=>naturalCmp(a.name||'',b.name||''))}catch(_){}

    return items;

},[documents,activeCategory,searchDeferred]);



const toggleDownloadSelect=id=>setSelectedForDownload(prev=>{const next=new Set(prev);next.has(id)?next.delete(id):next.add(id);return next});



const bulkDownload=()=>{

    const toDownload=documents.filter(d=>selectedForDownload.has(d.id));

    let downloaded=0;

    toDownload.forEach(doc=>{

    if(doc.downloadUrl){

        const _fid=doc.driveId||(!String(doc.id||'').startsWith('s')?doc.id:null);

        if(_fid&&typeof window._proxyDownload==='function'){window._proxyDownload(_fid,doc.name,'');downloaded++}

        else{window.open(doc.downloadUrl,'_blank','noopener,noreferrer');downloaded++}

    }else if(doc.content){

        const blob=new Blob([doc.content],{type:'text/plain;charset=utf-8'});

        const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(doc.name||'document')+'.txt';

        document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);downloaded++;

    }

    });

    if(downloaded>0)toast(downloaded+' файл(а) изтеглени','success');

    setSelectedForDownload(new Set());

};



const driveCount=documents.filter(d=>!d.isStatic).length;



