    REDACT: 'Редактиран файл',

    REDACT_FILE: 'Редактиран файл',

    UPDATE_BUDGET: 'Обновен бюджет',

    SEND_NOTIFICATION: 'Изпратено известие',

    SEND_EMAIL: 'Изпратен имейл',

